import { CircleCheckIcon } from "lucide-react"

import { Badge } from "@/components/ui/badge"
import {
  Empty,
  EmptyDescription,
  EmptyHeader,
  EmptyMedia,
  EmptyTitle,
} from "@/components/ui/empty"
import { Skeleton } from "@/components/ui/skeleton"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import {
  DashboardCard,
  DashboardCardCount,
  DashboardCardError,
} from "@/components/blocks/openlmis/dashboard-card"

/** A requisition waiting on the user; map your API's requisitions onto it. */
export type ApprovalRequisition = {
  id: string
  emergency: boolean
  program: { name: string }
  facility: { code: string; name: string }
  processingPeriod: { name: string }
  /** When it reached this approver, as an ISO date. */
  waitingSince: string
}

type ApprovalsTableProps = {
  /** Most urgent first; a placeholder shows until it is set. */
  requisitions: readonly ApprovalRequisition[] | undefined
  /** All that are waiting, when `requisitions` is only the first page of them. */
  total?: number
  failed?: boolean
  onRetry?: () => void
}

const formatDate = new Intl.DateTimeFormat(undefined, { dateStyle: "medium" })
  .format

/** The requisitions waiting on this user: a table with room, two lines each on a narrow card. */
export function ApprovalsTable({
  requisitions,
  total = requisitions?.length,
  failed = false,
  onRetry,
}: ApprovalsTableProps) {
  return (
    <DashboardCard
      badge={<DashboardCardCount failed={failed} value={total} />}
      description="Requisitions waiting for your approval, emergencies first."
      title="Awaiting Your Approval"
    >
      {failed && onRetry ? (
        <DashboardCardError onRetry={onRetry} />
      ) : requisitions === undefined ? (
        <div aria-busy className="flex flex-col gap-3">
          {["a", "b", "c", "d", "e"].map((row) => (
            <Skeleton className="h-10 w-full" key={row} />
          ))}
        </div>
      ) : requisitions.length === 0 ? (
        <Empty>
          <EmptyHeader>
            <EmptyMedia variant="icon">
              <CircleCheckIcon />
            </EmptyMedia>
            <EmptyTitle>Nothing To Approve</EmptyTitle>
            <EmptyDescription>
              Requisitions that need your approval appear here.
            </EmptyDescription>
          </EmptyHeader>
        </Empty>
      ) : (
        // Its own container, so the layout follows the card's width; the hidden one is out of the accessibility tree.
        <div className="@container/approvals">
          <div className="hidden @xl/approvals:block">
            <ApprovalsGrid requisitions={requisitions} />
          </div>
          <div className="@xl/approvals:hidden">
            <ApprovalsList requisitions={requisitions} />
          </div>
        </div>
      )}
    </DashboardCard>
  )
}

function EmergencyBadge({ emergency }: { emergency: boolean }) {
  return emergency ? <Badge variant="destructive">Emergency</Badge> : null
}

function ApprovalsGrid({
  requisitions,
}: {
  requisitions: readonly ApprovalRequisition[]
}) {
  return (
    <Table>
      <TableHeader>
        <TableRow>
          <TableHead>Program</TableHead>
          <TableHead>Facility</TableHead>
          <TableHead>Period</TableHead>
          <TableHead>Waiting Since</TableHead>
        </TableRow>
      </TableHeader>
      <TableBody>
        {requisitions.map((requisition) => (
          <TableRow key={requisition.id}>
            <TableCell>
              <div className="flex items-center gap-2">
                <span className="font-medium">{requisition.program.name}</span>
                <EmergencyBadge emergency={requisition.emergency} />
              </div>
            </TableCell>
            <TableCell>
              <div className="flex flex-col">
                <span>{requisition.facility.name}</span>
                <span className="text-xs text-muted-foreground">
                  {requisition.facility.code}
                </span>
              </div>
            </TableCell>
            <TableCell>{requisition.processingPeriod.name}</TableCell>
            <TableCell>
              <span className="text-muted-foreground">
                {formatDate(new Date(requisition.waitingSince))}
              </span>
            </TableCell>
          </TableRow>
        ))}
      </TableBody>
    </Table>
  )
}

/** Two lines per requisition: where and since when, then what for. */
function ApprovalsList({
  requisitions,
}: {
  requisitions: readonly ApprovalRequisition[]
}) {
  return (
    <ul className="flex flex-col divide-y">
      {requisitions.map((requisition) => (
        <li
          className="flex flex-col gap-1 py-3 first:pt-0 last:pb-0"
          key={requisition.id}
        >
          <div className="flex items-baseline justify-between gap-3">
            {/* Separate items, so the gap holds even where Latin names sit in a right-to-left line. */}
            <span className="flex min-w-0 items-baseline gap-1.5">
              <span className="truncate text-sm font-medium">
                {requisition.facility.name}
              </span>
              <span className="shrink-0 text-xs text-muted-foreground">
                {requisition.facility.code}
              </span>
            </span>
            <span className="shrink-0 text-xs text-muted-foreground">
              <span className="sr-only">Waiting since </span>
              {formatDate(new Date(requisition.waitingSince))}
            </span>
          </div>
          <div className="flex items-center gap-2 text-sm text-muted-foreground">
            {/* Only the program gives way; the period stays whole, and the dot reads as a comma. */}
            <span className="flex min-w-0 items-baseline gap-1.5">
              <span className="truncate">{requisition.program.name}</span>
              <span aria-hidden="true">·</span>
              <span className="sr-only">, </span>
              <span className="shrink-0">
                {requisition.processingPeriod.name}
              </span>
            </span>
            <EmergencyBadge emergency={requisition.emergency} />
          </div>
        </li>
      ))}
    </ul>
  )
}

"use client"

import {
  CircleCheckIcon,
  CircleXIcon,
  type LucideIcon,
  TriangleAlertIcon,
  WrenchIcon,
} from "lucide-react"

import { Skeleton } from "@/components/ui/skeleton"
import {
  DashboardCard,
  DashboardCardCount,
  DashboardCardError,
  formatCount,
} from "@/components/blocks/openlmis/dashboard-card"
import {
  StatusMeter,
  StatusMeterIcon,
  StatusMeterLabel,
  StatusMeterList,
  StatusMeterValue,
  type StatusMeterTone,
} from "@/components/openlmis/status-meter-list"

/** Cold chain equipment's functional statuses, best first. */
export const EQUIPMENT_STATUSES = [
  "FUNCTIONING",
  "NEEDS_ATTENTION",
  "AWAITING_REPAIR",
  "UNSERVICEABLE",
] as const

export type EquipmentStatus = (typeof EQUIPMENT_STATUSES)[number]

type StatusStyle = {
  label: string
  icon: LucideIcon
  tone: StatusMeterTone
}

/** The colours carry good-to-critical meaning, so each status also has its own icon and label. */
const STATUS_STYLE: Record<EquipmentStatus, StatusStyle> = {
  FUNCTIONING: {
    label: "Functioning",
    icon: CircleCheckIcon,
    tone: "success",
  },
  NEEDS_ATTENTION: {
    label: "Needs Attention",
    icon: TriangleAlertIcon,
    tone: "warning",
  },
  AWAITING_REPAIR: {
    label: "Awaiting Repair",
    icon: WrenchIcon,
    tone: "warning",
  },
  UNSERVICEABLE: {
    label: "Unserviceable",
    icon: CircleXIcon,
    tone: "destructive",
  },
}

type EquipmentStatusCardProps = {
  /** How much equipment is in each status; a placeholder shows until it is set. */
  counts: Record<EquipmentStatus, number> | undefined
  failed?: boolean
  onRetry?: () => void
}

/** How much cold chain equipment works, needs work or is out of service. */
export function EquipmentStatusCard({
  counts,
  failed = false,
  onRetry,
}: EquipmentStatusCardProps) {
  const total = counts
    ? EQUIPMENT_STATUSES.reduce((sum, status) => sum + counts[status], 0)
    : undefined

  return (
    <DashboardCard
      badge={<DashboardCardCount failed={failed} value={total} />}
      description="Cold chain equipment by functional status."
      title="Cold Chain Equipment"
    >
      {failed && onRetry ? (
        <DashboardCardError onRetry={onRetry} />
      ) : counts === undefined || total === undefined ? (
        <Skeleton className="h-40 w-full" />
      ) : (
        <StatusMeterList>
          {EQUIPMENT_STATUSES.map((status) => {
            const { label, icon, tone } = STATUS_STYLE[status]
            return (
              <StatusMeter
                key={status}
                max={total}
                tone={tone}
                value={counts[status]}
              >
                <StatusMeterIcon icon={icon} />
                <StatusMeterLabel>{label}</StatusMeterLabel>
                <StatusMeterValue>
                  {formatCount(counts[status])}
                </StatusMeterValue>
              </StatusMeter>
            )
          })}
        </StatusMeterList>
      )}
    </DashboardCard>
  )
}

"use client"

import { InfoIcon, LayoutDashboardIcon, PlusIcon } from "lucide-react"

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert"
import { Button } from "@/components/ui/button"
import {
  Empty,
  EmptyDescription,
  EmptyHeader,
  EmptyMedia,
  EmptyTitle,
} from "@/components/ui/empty"
import { ApprovalsTable } from "@/components/openlmis/home-dashboard/approvals-table"
import { EquipmentStatusCard } from "@/components/openlmis/home-dashboard/equipment-status"
import { RequisitionStatusMeter } from "@/components/openlmis/home-dashboard/requisition-status-meter"
import { RequisitionsByPeriod } from "@/components/openlmis/home-dashboard/requisitions-by-period"
import {
  Workspace,
  WorkspaceActions,
  WorkspaceContent,
  WorkspaceDescription,
  WorkspaceHeader,
  WorkspaceHeading,
  WorkspaceTitle,
} from "@/components/blocks/openlmis/workspace"
import { DashboardRow } from "@/components/blocks/openlmis/dashboard-card"
import {
  Stat,
  StatStrip,
} from "@/components/blocks/openlmis/stat-strip"

import {
  type DashboardAccess,
  type DashboardData,
  MOCK_ACCESS,
  MOCK_DASHBOARD,
  MOCK_USER,
} from "@/components/openlmis/home-dashboard/mock-dashboard"

const needsAttention = (counts: {
  AWAITING_REPAIR: number
  UNSERVICEABLE: number
}) => counts.AWAITING_REPAIR + counts.UNSERVICEABLE

type HomeDashboardProps = {
  /** Which parts the user's rights allow; the rest stay hidden. */
  access?: DashboardAccess
  data?: DashboardData
  firstName?: string
  /** Opens Add User, e.g. by navigating to the users list. */
  onAddUser?: () => void
}

/** The home screen: a greeting, headline numbers and the cards the user's rights allow. */
export function HomeDashboard({
  access = MOCK_ACCESS,
  data = MOCK_DASHBOARD,
  firstName = MOCK_USER.firstName,
  onAddUser,
}: HomeDashboardProps) {
  const nothingToShow = !Object.entries(access).some(
    ([part, allowed]) => part !== "manageUsers" && allowed
  )

  const stats = [
    access.approve && (
      <Stat
        key="approve"
        label="Requisitions To Approve"
        value={data.approvals.length}
      />
    ),
    access.convert && (
      <Stat
        key="convert"
        label="Requisitions To Convert"
        value={data.convertCount}
      />
    ),
    access.orders && (
      <Stat
        key="orders"
        label="Orders Not Received"
        value={data.openOrdersCount}
      />
    ),
    access.equipment && (
      <Stat
        key="equipment"
        label="Equipment Not Functioning"
        value={needsAttention(data.equipmentCounts)}
      />
    ),
  ].filter(Boolean)

  return (
    <Workspace>
      <WorkspaceHeader>
        <WorkspaceHeading>
          <WorkspaceTitle>Welcome, {firstName}</WorkspaceTitle>
          <WorkspaceDescription>
            {waitingSummary(data.approvals.length, data.convertCount, access)}
          </WorkspaceDescription>
        </WorkspaceHeading>
        {access.manageUsers && (
          <WorkspaceActions>
            <Button onClick={onAddUser} size="lg">
              <PlusIcon data-icon="inline-start" />
              Add User
            </Button>
          </WorkspaceActions>
        )}
      </WorkspaceHeader>
      <WorkspaceContent>
        {data.notifications.map((notification) => (
          <Alert key={notification.id}>
            <InfoIcon />
            {notification.title && (
              <AlertTitle>{notification.title}</AlertTitle>
            )}
            <AlertDescription>{notification.message}</AlertDescription>
          </Alert>
        ))}

        {nothingToShow && (
          <Empty>
            <EmptyHeader>
              <EmptyMedia variant="icon">
                <LayoutDashboardIcon />
              </EmptyMedia>
              <EmptyTitle>Nothing To Show Yet</EmptyTitle>
              <EmptyDescription>
                Your roles do not include any of the work this page summarizes.
              </EmptyDescription>
            </EmptyHeader>
          </Empty>
        )}

        {stats.length > 0 && <StatStrip>{stats}</StatStrip>}

        {access.requisitions && (
          <DashboardRow
            narrow={<RequisitionStatusMeter counts={data.statusCounts} />}
            wide={
              <RequisitionsByPeriod requisitions={data.recentRequisitions} />
            }
          />
        )}

        {(access.approve || access.equipment) && (
          <DashboardRow
            narrow={
              access.equipment && (
                <EquipmentStatusCard counts={data.equipmentCounts} />
              )
            }
            wide={
              access.approve && <ApprovalsTable requisitions={data.approvals} />
            }
          />
        )}
      </WorkspaceContent>
    </Workspace>
  )
}

const requisitions = (count: number) =>
  `${count} ${count === 1 ? "requisition" : "requisitions"}`

/** One sentence on what is waiting, from the counts this user's rights let them see. */
function waitingSummary(
  toApprove: number | undefined,
  toConvert: number | undefined,
  { approve, convert }: DashboardAccess
) {
  if (approve && convert && toApprove !== undefined && toConvert !== undefined)
    return `${requisitions(toApprove)} to approve and ${toConvert} to convert to orders.`
  if (approve && !convert && toApprove !== undefined)
    return `${requisitions(toApprove)} waiting for your approval.`
  if (convert && !approve && toConvert !== undefined)
    return `${requisitions(toConvert)} ready to convert to orders.`
  return approve || convert
    ? "What needs your attention today."
    : "An overview of your work in OpenLMIS."
}

"use client"

import { Skeleton } from "@/components/ui/skeleton"
import {
  DashboardCard,
  DashboardCardCount,
  DashboardCardError,
} from "@/components/blocks/openlmis/dashboard-card"
import { SegmentedMeter } from "@/components/openlmis/segmented-meter"

/** A sent requisition's steps, in the order it takes them. */
export const REQUISITION_PIPELINE = [
  "SUBMITTED",
  "AUTHORIZED",
  "IN_APPROVAL",
  "APPROVED",
  "RELEASED",
] as const

export type PipelineStatus = (typeof REQUISITION_PIPELINE)[number]

const LABELS = {
  SUBMITTED: "Submitted",
  AUTHORIZED: "Authorized",
  IN_APPROVAL: "In Approval",
  APPROVED: "Approved",
  RELEASED: "Released",
} as const satisfies Record<PipelineStatus, string>

type RequisitionStatusMeterProps = {
  /** How many requisitions stand at each step; a placeholder shows until it is set. */
  counts: Record<PipelineStatus, number> | undefined
  failed?: boolean
  onRetry?: () => void
  /** Fills the meter from the right on a right-to-left page. */
  dir?: "ltr" | "rtl"
  /** Formats each share, e.g. "43%"; fixed so a server render matches the browser. */
  locale?: string
}

/** Where sent requisitions stand, from submitted to released, as one segmented bar with a legend. */
export function RequisitionStatusMeter({
  counts,
  failed = false,
  onRetry,
  dir = "ltr",
  locale = "en-US",
}: RequisitionStatusMeterProps) {
  const total = counts
    ? REQUISITION_PIPELINE.reduce((sum, status) => sum + counts[status], 0)
    : undefined

  return (
    <DashboardCard
      badge={<DashboardCardCount failed={failed} value={total} />}
      description="Where sent requisitions stand today."
      title="Requisitions By Status"
    >
      {failed && onRetry ? (
        <DashboardCardError onRetry={onRetry} />
      ) : counts === undefined || total === undefined ? (
        <Skeleton className="h-36 w-full" />
      ) : (
        <SegmentedMeter
          dir={dir}
          locale={locale}
          segments={REQUISITION_PIPELINE.map((status) => ({
            id: status,
            label: LABELS[status],
            value: counts[status],
          }))}
        />
      )}
    </DashboardCard>
  )
}

export type RequisitionStatus =
  | "INITIATED"
  | "REJECTED"
  | "SUBMITTED"
  | "AUTHORIZED"
  | "IN_APPROVAL"
  | "APPROVED"
  | "RELEASED"
  | "RELEASED_WITHOUT_ORDER"
  | "SKIPPED"

/** The parts of a requisition the chart reads; map your API's requisitions onto it. */
export type PeriodRequisition = {
  status: RequisitionStatus
  processingPeriod: { startDate: string }
}

/** Sent on but not approved yet; drafts, rejections and skipped periods are left out. */
const IN_PROGRESS: ReadonlySet<RequisitionStatus> = new Set<RequisitionStatus>([
  "SUBMITTED",
  "AUTHORIZED",
  "IN_APPROVAL",
])
const APPROVED: ReadonlySet<RequisitionStatus> = new Set<RequisitionStatus>([
  "APPROVED",
  "RELEASED",
  "RELEASED_WITHOUT_ORDER",
])

export type MonthTotals = {
  /** `YYYY-MM`, the month the requisitions' periods start. */
  month: string
  inProgress: number
  approved: number
}

/** The latest months with requisitions, oldest first; monthly and quarterly periods meet on one timeline. */
export function totalsByMonth(
  requisitions: readonly PeriodRequisition[],
  limit = 6
): MonthTotals[] {
  const months = new Map<string, MonthTotals>()

  for (const { status, processingPeriod } of requisitions) {
    const group = IN_PROGRESS.has(status)
      ? "inProgress"
      : APPROVED.has(status)
        ? "approved"
        : null
    if (!group) continue
    const month = processingPeriod.startDate.slice(0, 7)
    const totals = months.get(month) ?? { month, inProgress: 0, approved: 0 }
    totals[group] += 1
    months.set(month, totals)
  }

  const totals = [...months.values()]
  // oxlint-disable-next-line unicorn/no-array-sort -- sorts a copy; toSorted needs the ES2023 lib
  totals.sort((a, b) => a.month.localeCompare(b.month))
  return totals.slice(-limit)
}

/** Whether a month's tick shows its year: on the first month and wherever the year changes. */
export function showsYear(
  months: readonly MonthTotals[],
  index: number
): boolean {
  return (
    index === 0 ||
    months[index - 1]?.month.slice(0, 4) !== months[index]?.month.slice(0, 4)
  )
}

"use client"

import { BarChartIcon } from "lucide-react"
import { useMemo } from "react"
import {
  Bar,
  BarChart,
  CartesianGrid,
  LabelList,
  Rectangle,
  type RectangleProps,
  XAxis,
  YAxis,
} from "recharts"

import {
  type ChartConfig,
  ChartContainer,
  ChartLegend,
  ChartLegendContent,
  ChartTooltip,
  ChartTooltipContent,
} from "@/components/ui/chart"
import {
  Empty,
  EmptyDescription,
  EmptyHeader,
  EmptyMedia,
  EmptyTitle,
} from "@/components/ui/empty"
import { Skeleton } from "@/components/ui/skeleton"
import {
  DashboardCard,
  DashboardCardCount,
  DashboardCardError,
  formatCount,
} from "@/components/blocks/openlmis/dashboard-card"

import {
  type MonthTotals,
  type PeriodRequisition,
  showsYear,
  totalsByMonth,
} from "@/components/openlmis/home-dashboard/periods"

const TITLE = "Requisitions By Period"

const config = {
  inProgress: { label: "In Progress", color: "var(--chart-2)" },
  approved: { label: "Approved", color: "var(--chart-4)" },
} satisfies ChartConfig

/** Month and year from a `YYYY-MM` key, read in UTC so a period never slips into the month before. */
const monthFormat = (options: Intl.DateTimeFormatOptions) => {
  const formatter = new Intl.DateTimeFormat(undefined, {
    ...options,
    timeZone: "UTC",
  })
  return (key: string) => formatter.format(new Date(`${key}-01T00:00:00Z`))
}
const formatMonthYear = monthFormat({ month: "short", year: "numeric" })
const formatMonth = monthFormat({ month: "short" })
const formatYear = monthFormat({ year: "numeric" })

type RequisitionsByPeriodProps = {
  /** A placeholder shows until it is set. */
  requisitions: readonly PeriodRequisition[] | undefined
  failed?: boolean
  onRetry?: () => void
  /** Mirrors the axes for a right-to-left page. */
  dir?: "ltr" | "rtl"
}

/** Sent requisitions in each of the latest months, split into still in progress and approved. */
export function RequisitionsByPeriod({
  requisitions,
  failed = false,
  onRetry,
  dir = "ltr",
}: RequisitionsByPeriodProps) {
  const months = useMemo(
    () => (requisitions ? totalsByMonth(requisitions) : undefined),
    [requisitions]
  )
  const total = months?.reduce(
    (sum, month) => sum + month.inProgress + month.approved,
    0
  )

  return (
    <DashboardCard
      badge={<DashboardCardCount failed={failed} value={total} />}
      description="Sent requisitions by the month their period starts."
      title={TITLE}
    >
      {failed && onRetry ? (
        <DashboardCardError onRetry={onRetry} />
      ) : months === undefined ? (
        <Skeleton className="h-64 w-full" />
      ) : months.length === 0 ? (
        <Empty>
          <EmptyHeader>
            <EmptyMedia variant="icon">
              <BarChartIcon />
            </EmptyMedia>
            <EmptyTitle>No Requisitions Yet</EmptyTitle>
            <EmptyDescription>
              Requisitions appear here once they are submitted.
            </EmptyDescription>
          </EmptyHeader>
        </Empty>
      ) : (
        <MonthChart dir={dir} months={months} />
      )}
    </DashboardCard>
  )
}

function MonthChart({
  months,
  dir,
}: {
  months: MonthTotals[]
  dir: "ltr" | "rtl"
}) {
  const isRtl = dir === "rtl"

  return (
    <>
      {/* Sized by height, so the plot fills whatever width the card has. */}
      <ChartContainer className="aspect-auto h-64 w-full" config={config}>
        <BarChart accessibilityLayer data={months} margin={{ top: 20 }}>
          <CartesianGrid vertical={false} />
          {/* Every month is labelled; there are at most six, so none is skipped. */}
          <XAxis
            axisLine={false}
            dataKey="month"
            height={36}
            interval={0}
            reversed={isRtl}
            tick={<MonthTick months={months} />}
            tickLine={false}
            tickMargin={4}
          />
          <YAxis
            allowDecimals={false}
            axisLine={false}
            orientation={isRtl ? "right" : "left"}
            tickFormatter={formatCount}
            tickLine={false}
            width={32}
          />
          <ChartTooltip
            content={
              <ChartTooltipContent
                labelFormatter={(month) => formatMonthYear(String(month))}
              />
            }
            cursor={false}
          />
          {/* Recharts sorts the legend by name; the stacking order reads better. */}
          <ChartLegend content={<ChartLegendContent />} itemSorter={null} />
          {/* The card-coloured stroke is the 2px gap that keeps stacked segments apart. */}
          <Bar
            dataKey="inProgress"
            fill="var(--color-inProgress)"
            maxBarSize={24}
            shape={InProgressSegment}
            stackId="month"
            stroke="var(--card)"
            strokeWidth={2}
          />
          <Bar
            dataKey="approved"
            fill="var(--color-approved)"
            maxBarSize={24}
            radius={[4, 4, 0, 0]}
            stackId="month"
            stroke="var(--card)"
            strokeWidth={2}
          >
            <LabelList
              className="fill-muted-foreground"
              formatter={(value) =>
                typeof value === "number" ? formatCount(value) : value
              }
              position="top"
              valueAccessor={(entry: { payload: MonthTotals }) =>
                entry.payload.inProgress + entry.payload.approved
              }
            />
          </Bar>
        </BarChart>
      </ChartContainer>
      <table className="sr-only">
        <caption>{TITLE}</caption>
        <thead>
          <tr>
            <th scope="col">Month</th>
            <th scope="col">{config.inProgress.label}</th>
            <th scope="col">{config.approved.label}</th>
          </tr>
        </thead>
        <tbody>
          {months.map((month) => (
            <tr key={month.month}>
              <th scope="row">{formatMonthYear(month.month)}</th>
              <td>{formatCount(month.inProgress)}</td>
              <td>{formatCount(month.approved)}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </>
  )
}

type MonthTickProps = {
  x?: number
  y?: number
  index?: number
  payload?: { value: string }
  months: readonly MonthTotals[]
}

/** The month, with its year beneath where the year starts or changes, so six ticks fit a phone. */
function MonthTick({
  x = 0,
  y = 0,
  index = 0,
  payload,
  months,
}: MonthTickProps) {
  if (!payload) return null
  return (
    <text
      className="fill-muted-foreground text-xs"
      textAnchor="middle"
      x={x}
      y={y}
    >
      <tspan dy="0.8em" x={x}>
        {formatMonth(payload.value)}
      </tspan>
      {showsYear(months, index) && (
        <tspan dy="1.3em" x={x}>
          {formatYear(payload.value)}
        </tspan>
      )}
    </text>
  )
}

/** The lower segment, rounded on top only when nothing is stacked above it. */
function InProgressSegment(props: RectangleProps & { payload?: MonthTotals }) {
  return (
    <Rectangle {...props} radius={props.payload?.approved ? 0 : [4, 4, 0, 0]} />
  )
}

